//! Literal wire expectations from xterm ctlseqs: Normal tracking mode and
//! Extended coordinates (1005/1006/1015), not generated by a baseline encoder.
//! https://invisible-island.net/xterm/ctlseqs/ctlseqs.html
use jterm_engine::{
    mode_mutation::{apply_ember_mode, ModeNamespace},
    parser::{Event, Parser},
    protocol_state::{ProtocolState, TerminalModes},
    screen::ScreenState,
};

// None, Shift, Meta, Shift+Meta, Ctrl, Shift+Ctrl, Meta+Ctrl, all.
const RELEASES: [(u8, u8, &[u8]); 8] = [
    (0, 35, b"\x1b[35;95;301M"),
    (4, 39, b"\x1b[39;95;301M"),
    (8, 43, b"\x1b[43;95;301M"),
    (12, 47, b"\x1b[47;95;301M"),
    (16, 51, b"\x1b[51;95;301M"),
    (20, 55, b"\x1b[55;95;301M"),
    (24, 59, b"\x1b[59;95;301M"),
    (28, 63, b"\x1b[63;95;301M"),
];

#[test]
fn legacy_releases_preserve_every_modifier_combination_only() {
    for reporting in [1000, 1002, 1003] {
        for encoding in [0, 1005, 1015] {
            let mut modes = TerminalModes::default();
            modes.insert(reporting);
            modes.insert(encoding);
            for (modifiers, cb, decimal) in RELEASES {
                // All button IDs and non-modifier high bits. A release must not
                // turn into a motion/wheel/extended-button event.
                for other in (0..=u8::MAX).filter(|bits| bits & 0x1c == 0) {
                    let expected = match encoding {
                        1005 => vec![27, 91, 77, cb, 127, 0xc5, 0x8d],
                        1015 => decimal.to_vec(),
                        _ => vec![27, 91, 77, cb, 127, 255],
                    };
                    assert_eq!(
                        modes.get_mouse_release_report(modifiers | other, 94, 300),
                        Some(expected),
                        "reporting={reporting} encoding={encoding} modifiers={modifiers} other={other}"
                    );
                }
            }
            modes.remove(&reporting);
            for (modifiers, _, _) in RELEASES {
                assert_eq!(modes.get_mouse_release_report(modifiers, 94, 300), None);
            }
        }
    }
}

#[test]
fn sgr_release_keeps_button_identity_and_all_modifier_combinations() {
    let mut modes = TerminalModes::default();
    modes.insert(1000);
    modes.insert(1005);
    modes.insert(1015);
    modes.insert(1006);
    for (modifier, buttons) in [
        (0, ["0", "1", "2"]),
        (4, ["4", "5", "6"]),
        (8, ["8", "9", "10"]),
        (12, ["12", "13", "14"]),
        (16, ["16", "17", "18"]),
        (20, ["20", "21", "22"]),
        (24, ["24", "25", "26"]),
        (28, ["28", "29", "30"]),
    ] {
        for (button, decimal) in buttons.into_iter().enumerate() {
            assert_eq!(
                modes.get_mouse_release_report(modifier | button as u8, 94, 300),
                Some(format!("\x1b[<{decimal};95;301m").into_bytes())
            );
        }
    }
    // Preserve the pre-existing unrestricted SGR Cb API too.
    assert_eq!(
        modes.get_mouse_release_report(255, 0, 0).unwrap(),
        b"\x1b[<255;1;1m"
    );
}

fn feed(parser: &mut Parser, screen: &mut ScreenState, protocol: &mut ProtocolState, bytes: &[u8]) {
    parser.begin_feed();
    let mut at = 0;
    loop {
        let step = parser.next(&bytes[at..]);
        at += step.consumed;
        match step.event {
            Some(Event::Csi {
                params,
                private_prefix: Some(b'?'),
                intermediates,
                final_byte,
                ..
            }) => {
                // Explicit test host routing; whole CSI mode dispatch is host-owned.
                assert!(intermediates.is_empty());
                assert!(matches!(final_byte, b'h' | b'l'));
                for mode in params {
                    assert!(apply_ember_mode(
                        screen,
                        protocol,
                        ModeNamespace::DecPrivate,
                        mode,
                        final_byte == b'h'
                    ));
                }
            }
            None => {
                assert_eq!(at, bytes.len());
                break;
            }
            other => panic!("unexpected parser event {other:?}"),
        }
    }
}

#[test]
fn fragmented_mode_switches_preserve_release_modifiers_and_precedence() {
    let steps: &[(&[u8], Option<&[u8]>)] = &[
        (b"\x1b[?1000h", Some(b"\x1b[M?\x7f\xff")),
        (b"\x1b[?1005h", Some(b"\x1b[M?\x7f\xc5\x8d")),
        (b"\x1b[?1015h", Some(b"\x1b[63;95;301M")),
        (b"\x1b[?1006h", Some(b"\x1b[<30;95;301m")),
        (b"\x1b[?1006l", Some(b"\x1b[63;95;301M")),
        (b"\x1b[?1015l", Some(b"\x1b[M?\x7f\xc5\x8d")),
        (b"\x1b[?1005l", Some(b"\x1b[M?\x7f\xff")),
        (b"\x1b[?1000l", None),
        (b"\x1b[?1005h", None),
        (b"\x1b[?1002h", Some(b"\x1b[M?\x7f\xc5\x8d")),
        (b"\x1b[?1002l", None),
        (b"\x1b[?1003h", Some(b"\x1b[M?\x7f\xc5\x8d")),
    ];
    for split in 0..=8 {
        let mut parser = Parser::new(jterm_engine::parser::ParserLimits {
            pending_bytes: 128,
            kitty_recovery_bytes: 32,
        });
        let mut screen = ScreenState::new(2, 2);
        let mut protocol = ProtocolState::default();
        let mut previous: Option<&[u8]> = None;
        for &(command, expected) in steps {
            feed(&mut parser, &mut screen, &mut protocol, &command[..split]);
            if split < command.len() {
                assert_eq!(
                    protocol
                        .modes()
                        .get_mouse_release_report(30, 94, 300)
                        .as_deref(),
                    previous
                );
            }
            feed(&mut parser, &mut screen, &mut protocol, &command[split..]);
            assert_eq!(
                protocol
                    .modes()
                    .get_mouse_release_report(30, 94, 300)
                    .as_deref(),
                expected
            );
            previous = expected;
        }
    }
}
